// VAT Renderer Integration Example
// This demonstrates how to use the VAT renderer with a goat NPC archetype.
// ---------------------------------------------------------------------
// Note: This is a minimal example for demonstration purposes.
// Actual integration would require:
// 1. Loading a static mesh for the goat
// 2. Loading VAT textures (generated by external tool)
// 3. Setting up the renderer in main.c
// 4. Rendering in the game loop
// ---------------------------------------------------------------------
#include "vat_renderer.h"

#include <stdio.h>
#include <stdlib.h>

// Example: Simple goat NPC integration
typedef struct {
    int enabled;
    int vat_instance_idx;
    int mesh_idx;
    int texture_idx;
    int frame_count;
    float anim_time;
    float anim_speed;
    Vector3 position;
    float yaw;
    float scale;
} GoatNPC;

static GoatNPC g_goat = { 0 };
static VatRenderer g_vat_renderer = { 0 };

// Initialize VAT renderer and load assets (call during game init)
void vat_example_init(void) {
    // Initialize VAT renderer with max 64 instances
    vat_renderer_init(&g_vat_renderer, 64);
    
    // Load shaders (desktop GLSL 330)
    // Note: In production, you'd also load GLSL ES 100 for Android
    if (vat_renderer_load_shader_gl330(&g_vat_renderer,
                                       "assets/shaders/glsl330/vat.vs",
                                       "assets/shaders/glsl330/vat.fs") != 0) {
        printf("Failed to load GLSL 330 shaders\n");
    }
    
    // Load static mesh (replace with actual goat model path)
    // int mesh_idx = vat_renderer_load_mesh(&g_vat_renderer, "assets/models/animales/cabra.glb");
    
    // Load VAT texture (replace with actual VAT texture path)
    // Note: VAT texture has dimensions: width=vertex_count, height=frame_count
    // Example: 1000 vertices, 24 frames -> 1000x24 texture
    // int texture_idx = vat_renderer_load_vat_texture(&g_vat_renderer, 
    //                                                  "assets/models/animales/cabra_vat.png",
    //                                                  24);
    
    // Create instance for the goat
    // g_goat.vat_instance_idx = vat_renderer_add_instance(&g_vat_renderer, 0); // archetype_id = 0
    
    // g_goat.enabled = 1;
    // g_goat.mesh_idx = 0;  // mesh_idx from load_mesh
    // g_goat.texture_idx = 0;  // texture_idx from load_vat_texture
    // g_goat.frame_count = 24;  // from texture
    // g_goat.anim_time = 0.0f;
    // g_goat.anim_speed = 1.0f;
    // g_goat.position = (Vector3){ 0, 0, 0 };
    // g_goat.yaw = 0.0f;
    // g_goat.scale = 1.0f;
}

// Update goat animation (call each frame)
void vat_example_update(float dt) {
    if (!g_goat.enabled) return;
    
    // Update VAT instance
    vat_renderer_update_instance(&g_vat_renderer, g_goat.vat_instance_idx, dt);
}

// Draw goat (call during rendering)
void vat_example_draw(void) {
    if (!g_goat.enabled) return;
    
    // Draw the VAT instance
    vat_renderer_draw_instance(&g_vat_renderer, g_goat.vat_instance_idx);
}

// Cleanup (call on shutdown)
void vat_example_shutdown(void) {
    vat_renderer_clear_instances(&g_vat_renderer);
    vat_renderer_shutdown(&g_vat_renderer);
}

